        'id': 'm3',
        'fromId': 'main',
        'toId': 'other/main',
        'text': 'legacy',
        'sentAt': '2026-01-01T00:00:00Z',
        'hops': 0,
      });
      expect(legacy.kind, AgentMessageKind.agent);
    });
  });

  group('FileSessionPresenceStore', () {
    late MemoryExecutionEnv env;
    var clock = DateTime.utc(2026, 1, 1, 12);

