      _fs,
      await _createSessionFilePath(sessionId, createdAt, cwd),
      cwd: cwd,
      sessionId: sessionId,
      parentSessionPath: parentSessionPath ?? source.path,
      metadata: metadata ?? source.metadata,
      ioRetry: _ioRetry,
