  @override
  Future<List<SessionMetadata>> list({String? cwd}) async {
    final sessions = await _collectRootSessions();
    if (cwd != null) {
      sessions.retainWhere((m) => m.cwd == cwd);
    }
    sessions.sort(compareSessionActivity);
    return sessions;
