          metadata: {'agent': 'cli', 'model': _agent.state.model.id},
        ),
      );
      if (name != null && name.isNotEmpty) {
        await session.appendSessionName(name);
      }
      return session;
    } on SessionException catch (error) {
      final fallbackRoot = '${config.homeDir ?? _env.cwd}/.fah/sessions';
