        {'id': 'scout', 'message': 'one more pass'},
        null,
        null,
      ),
    );
    expect(sent, contains('child resumed'));
    expect(cli.subagentManager['scout']!.status, SubagentStatus.completed);

    io.sendLine('/exit');
    await run;
    expect(fake.calls, 4);
  });

