    '/tasks folds a supersedes chain into ONE logical entry (AC5 CLI half)',
    () async {
      final fake = FakeStreamFunction([
        // Generation 1: background spawn → parent wrap-up → child result →
        // async-result re-wake.
        toolTurn([
          taskCall('t1', {
            'context': 'repo state',
            'background': true,
            'tasks': [
