      lastUpdatedAt: DateTime.fromMillisecondsSinceEpoch(entry.mtimeMs),
      sizeBytes: entry.size,
    );
  } on SessionException catch (error) {
    if (error.code != SessionErrorCode.invalidSession) rethrow;
    return null;
  }
}

