      } else {
        final file = _files[child];
        if (file != null) files[child] = Uint8List.fromList(file.bytes);
      }
    }
  }

  if (_dirs.contains(root)) walk(root);
  return MemoryFsSnapshot(dirs: dirs, files: files);
}

