    () async {
      final fake = FakeStreamFunction([
        // Generation 1: background spawn → parent wrap-up → child result →
        // async-result re-wake.
        toolTurn([
          taskCall('t1', {
            'context': 'repo state',
            'background': true,
            'tasks': [
              {'name': 'Scout', 'task': 'survey the repo'},
            ],
          }),
        ]),
        textTurn('delegated the survey'),
        textTurn('survey says: all quiet'),
        textTurn('noted'),
