        toolTurn([
          taskCall('t2', {
            'context': 'repo state',
            'background': true,
            'tasks': [
              {'name': 'Scout', 'task': 'survey again'},
            ],
          }),
        ]),
        textTurn('delegated again'),
        textTurn('second survey done'),
        textTurn('noted 2'),
      ]);
      final cli = cliFor(fake.call);
      final run = cli.run();
      io.sendLine('delegate it');
      await waitForIt(() => fake.calls == 4 && !cli.isBusy);
      io.sendLine('again');
