if (pid != null && _pidAlive != null) {
 if (_pidAlive!(pid)) return; // live process may resume — keep
} else {
 final aged = touched ?? _fromMtimeMs(info.mtimeMs);
 if (aged == null || !aged.isBefore(cleanupCutoff)) return; // within grace
}
await remove
``

